    return false;
}else if("".equals(npi) && profile.equals("preinscrit")){
    String id = FormUtil.getElementParameterName(element);
    formData.addFormError(id, "Vous devez être préinscrit au RSU pour pouvoir passer une demande de réclamation de type "+fieldValue);
    return false;
}else if(profile.equals("inscpreinsc") && !(statusDemande.equals("traité par la commission") || npiExists() ) ){
    String id = FormUtil.getElementParameterName(element);
    formData.addFormError(id, "Vous devez être inscrit au RSU ou vérifier votre npi chez l'ANIP pour pouvoir passer une demande de réclamation de type "+fieldValue);
    return false;
}else{
    return true;
}
